import numpy as np

WIN = 200
rng = np.random.default_rng(3)

def stream(worn, blocks):
    parts = []
    for _ in range(blocks):
        load = np.exp(rng.uniform(np.log(0.4), np.log(2.0)))
        rough = (0.16 if worn else 0.08) * np.exp(rng.normal(0.0, 0.25))
        parts.append(load * 2.6 + rough * load * rng.normal(0.0, 1.0, WIN))
    return np.concatenate(parts)

healthy = stream(False, 90).reshape(-1, WIN)
worn = stream(True, 90).reshape(-1, WIN)
block = np.vstack([healthy, worn])
y = np.concatenate([np.zeros(90, int), np.ones(90, int)])

chatter = np.mean(np.abs(np.diff(block, axis=1)), axis=1)
rms = np.sqrt((block ** 2).mean(axis=1))
columns = {"mean current": block.mean(axis=1), "chatter": chatter, "chatter over rms": chatter / rms}

order = np.random.default_rng(9).permutation(y.size)
train, test = order[:120], order[120:]

def sweep(values):
    best_cut, best_sign, best_score = 0.0, 1, -1.0
    for cut in np.unique(values[train]):
        for sign in (1, -1):
            guess = (values[train] * sign > cut * sign).astype(int)
            score = np.mean(guess == y[train])
            if score > best_score:
                best_cut, best_sign, best_score = cut, sign, score
    on_test = (values[test] * best_sign > best_cut * best_sign).astype(int)
    return np.mean(on_test == y[test])

for name, values in columns.items():
    print(name, round(sweep(values), 3))

