import numpy as np

def bench(n, worn, rng):
    load = rng.normal(0.0, 1.0, n)
    rms_db = 3.0 + 0.9 * load + rng.normal(0.0, 0.15, n)
    hf_db = (1.6 if worn else 1.0) + 0.9 * load + rng.normal(0.0, 0.15, n)
    return np.column_stack([rms_db, hf_db])

def rare_fault_log():
    gen = np.random.default_rng(19)
    good, bad = bench(1200, False, gen), bench(60, True, gen)
    train = np.vstack([good[:900], bad[:45]])
    y_train = np.concatenate([np.zeros(900, int), np.ones(45, int)])
    test = np.vstack([good[900:], bad[45:]])
    y_test = np.concatenate([np.zeros(300, int), np.ones(15, int)])
    return train, y_train, test, y_test

def fault_score(X_train, y_train, X_query, k=15):
    out = []
    for row in X_query:
        gap = ((X_train - row) ** 2).sum(axis=1)
        out.append(y_train[np.argsort(gap)[:k]].mean())
    return np.array(out)

X_train, y_train, X_test, y_test = rare_fault_log()
model = (fault_score(X_train, y_train, X_test) > 0.2).astype(int)
constant = np.zeros(y_test.shape, dtype=int)

def per_class(guess):
    recalls = [float(np.mean(guess[y_test == label] == label)) for label in (0, 1)]
    return recalls, sum(recalls) / len(recalls)

for name, guess in (("model", model), ("constant", constant)):
    recalls, balanced = per_class(guess)
    print(name, "plain accuracy", round(float(np.mean(guess == y_test)), 4),
          "per class", [round(r, 3) for r in recalls], "balanced", round(balanced, 4))

