import numpy as np

def sample(n, rng):
    current = rng.uniform(1.0, 6.0, n)
    rise = 2.4 * current ** 2 * 0.6 + 3.0 + rng.normal(0.0, 2.5, n)
    return current, rise

def powers(current, degree):
    scaled = (current - 3.5) / 2.5
    return np.column_stack([scaled ** p for p in range(degree + 1)])

def rmse(a, b):
    return float(np.sqrt(np.mean((a - b) ** 2)))

def linear(A, w):
    return (A * w).sum(axis=1)

def gram(A):
    return np.einsum("ij,ik->jk", A, A)

DEGREE = 9
gen = np.random.default_rng(14)
x_train, y_train = sample(12, gen)
x_test, y_test = sample(300, gen)
A_train, A_test = powers(x_train, DEGREE), powers(x_test, DEGREE)

def ridge(A, y, lam):
    eye = np.eye(A.shape[1])
    eye[0, 0] = 0.0
    return np.linalg.solve(gram(A) + lam * eye, (A * y[:, None]).sum(axis=0))

print("penalty  held out error  largest weight")
for lam in (0.0, 0.001, 0.01, 0.1, 1.0, 10.0):
    w = ridge(A_train, y_train, lam)
    print(str(lam).ljust(8), str(round(rmse(y_test, linear(A_test, w)), 3)).rjust(15), str(round(float(np.abs(w).max()), 1)).rjust(15))

loose = ridge(A_train, y_train, 0.0)
tight = ridge(A_train, y_train, 0.1)
print("largest weight falls from", round(float(np.abs(loose).max()), 1), "to", round(float(np.abs(tight).max()), 1))

