    return (A * w).sum(axis=1)

def sigmoid(z):
    out = np.empty(z.shape, dtype=float)
    high = z >= 0
    out[high] = 1.0 / (1.0 + np.exp(-z[high]))
    low = np.exp(z[~high])
    out[~high] = low / (1.0 + low)
    return out

def log_loss(A, y, w):
    p = np.clip(sigmoid(linear(A, w)), 1e-12, 1 - 1e-12)
    return float(-np.mean(y * np.log(p) + (1 - y) * np.log(1 - p)))

