    X = np.vstack([bench(n, False, gen), bench(n, True, gen)])
    y = np.concatenate([np.zeros(n, int), np.ones(n, int)])
    order = np.random.default_rng(seed + 40).permutation(y.size)
    X, y = X[order], y[order]
    keep = int(0.7 * y.size)
    mu, sd = X[:keep].mean(axis=0), X[:keep].std(axis=0)
    Z = (X - mu) / sd
    A = np.column_stack([np.ones(Z.shape[0]), Z])
    return A[:keep], y[:keep], A[keep:], y[keep:]

def linear(A, w):
    return (A * w).sum(axis=1)

def sigmoid(z):
    out = np.empty(z.shape, dtype=float)
    high = z >= 0
    out[high] = 1.0 / (1.0 + np.exp(-z[high]))
    low = np.exp(z[~high])
    out[~high] = low / (1.0 + low)
    return out

def log_loss(A, y, w):
    p = np.clip(sigmoid(linear(A, w)), 1e-12, 1 - 1e-12)
    return float(-np.mean(y * np.log(p) + (1 - y) * np.log(1 - p)))

