def gradient(A, y, w):
    return (A * (sigmoid(linear(A, w)) - y)[:, None]).sum(axis=0) / y.size

def descend(A, y, rate, steps):
    w = np.zeros(A.shape[1])
    marks = {}
    for step in range(steps + 1):
        if step in (0, 50, 200, 600):
            marks[step] = w.copy()
        w = w - rate * gradient(A, y, w)
    return w, marks

w, marks = descend(A_train, y_train, 0.5, 600)
for step in sorted(marks):
    held = np.mean((sigmoid(linear(A_test, marks[step])) > 0.5).astype(int) == y_test)
    print("step", step, "loss", round(log_loss(A_train, y_train, marks[step]), 4),
          "held out accuracy", round(float(held), 3))
print("final weights", np.round(w, 3))

