            if left.sum() == 0 or (~left).sum() == 0:
                continue
            score = (left.sum() * gini(y[left]) + (~left).sum() * gini(y[~left])) / y.size
            if score < best_score:
                best_col, best_cut, best_score = col, float(cut), score
    return best_col, best_cut, best_score

def grow(X, y, depth):
    leaf = int(np.bincount(y, minlength=2).argmax())
    if depth == 0 or y.size < 8 or np.unique(y).size == 1:
        return leaf
    col, cut, _ = best_split(X, y)
    if col is None:
        return leaf
    left = X[:, col] <= cut
    return (col, cut, grow(X[left], y[left], depth - 1), grow(X[~left], y[~left], depth - 1))

def ask(node, row):
    while isinstance(node, tuple):
        col, cut, low, high = node
        node = low if row[col] <= cut else high
    return node

def tree_accuracy(node, X, y):
    return float(np.mean(np.array([ask(node, r) for r in X]) == y))

NAMES = ["rms in decibels", "high frequency in decibels"]
X_train, y_train, X_test, y_test = loft()
node = grow(X_train, y_train, 6)
base = tree_accuracy(node, X_test, y_test)
gen = np.random.default_rng(13)

print("held out accuracy with everything intact", round(base, 3))

for col, name in enumerate(NAMES):
    drops = []
    for _ in range(5):
        broken = X_test.copy()
        # TODO: keep the column and destroy its pairing with the rows
        drops.append(base - tree_accuracy(node, broken, y_test))
    print(name.ljust(28), "drop", round(float(np.mean(drops)), 4))

