import numpy as np

def bench(n, worn, rng):
    load = rng.normal(0.0, 1.0, n)
    rms_db = 3.0 + 0.9 * load + rng.normal(0.0, 0.15, n)
    hf_db = (1.6 if worn else 1.0) + 0.9 * load + rng.normal(0.0, 0.15, n)
    return np.column_stack([rms_db, hf_db])

def loft(n=300, seed=5):
    gen = np.random.default_rng(seed)
    X = np.vstack([bench(n, False, gen), bench(n, True, gen)])
    y = np.concatenate([np.zeros(n, int), np.ones(n, int)])
    order = np.random.default_rng(seed + 3).permutation(y.size)
    X, y = X[order], y[order]
    keep = int(0.7 * y.size)
    return X[:keep], y[:keep], X[keep:], y[keep:]

CUTS = np.arange(5, 100, 5)

def gini(labels):
    if labels.size == 0:
        return 0.0
    share = np.bincount(labels, minlength=2) / labels.size
    return float(1.0 - (share ** 2).sum())

def best_split(X, y):
    best_col, best_cut, best_score = None, None, gini(y)
    for col in range(X.shape[1]):
        for cut in np.percentile(X[:, col], CUTS):
            left = X[:, col] <= cut
            if left.sum() == 0 or (~left).sum() == 0:
                continue
            score = (left.sum() * gini(y[left]) + (~left).sum() * gini(y[~left])) / y.size
            if score < best_score:
                best_col, best_cut, best_score = col, float(cut), score
    return best_col, best_cut, best_score

def grow(X, y, depth):
    leaf = int(np.bincount(y, minlength=2).argmax())
    if depth == 0 or y.size < 8 or np.unique(y).size == 1:
        return leaf
    col, cut, _ = best_split(X, y)
    if col is None:
        return leaf
    left = X[:, col] <= cut
    return (col, cut, grow(X[left], y[left], depth - 1), grow(X[~left], y[~left], depth - 1))

def ask(node, row):
    while isinstance(node, tuple):
        col, cut, low, high = node
        node = low if row[col] <= cut else high
    return node

def tree_accuracy(node, X, y):
    return float(np.mean(np.array([ask(node, r) for r in X]) == y))

NAMES = ["rms in decibels", "high frequency in decibels"]
X_train, y_train, X_test, y_test = loft()
node = grow(X_train, y_train, 6)
base = tree_accuracy(node, X_test, y_test)
gen = np.random.default_rng(13)

print("held out accuracy with everything intact", round(base, 3))

for col, name in enumerate(NAMES):
    drops = []
    for _ in range(5):
        broken = X_test.copy()
        broken[:, col] = gen.permutation(broken[:, col])
        drops.append(base - tree_accuracy(node, broken, y_test))
    print(name.ljust(28), "drop", round(float(np.mean(drops)), 4))

wide_train = np.column_stack([X_train, gen.normal(0.0, 1.0, X_train.shape[0])])
wide_test = np.column_stack([X_test, gen.normal(0.0, 1.0, X_test.shape[0])])
wide_node = grow(wide_train, y_train, 6)
wide_base = tree_accuracy(wide_node, wide_test, y_test)
drops = []
for _ in range(5):
    broken = wide_test.copy()
    broken[:, 2] = gen.permutation(broken[:, 2])
    drops.append(wide_base - tree_accuracy(wide_node, broken, y_test))
print("a column of pure noise drops", round(float(np.mean(drops)), 4), "on a tree grown with it present")

