import numpy as np

WIN, BLOCKS, UNITS = 200, 30, 12

def raw_session(unit, worn):
    gen = np.random.default_rng(200 + unit)
    calib = gen.normal(0.0, 0.6)
    parts = []
    for _ in range(BLOCKS):
        load = np.exp(gen.uniform(np.log(0.4), np.log(2.0)))
        rough = (0.16 if worn else 0.08) * np.exp(gen.normal(0.0, 0.25))
        parts.append(load * 2.6 + calib * 0.15 + rough * load * gen.normal(0.0, 1.0, WIN))
    return np.concatenate(parts)

def is_worn(unit):
    return unit % 2 == 1

def features(signal):
    block = signal.reshape(-1, WIN)
    ac = block - block.mean(axis=1, keepdims=True)
    level = np.sqrt((block ** 2).mean(axis=1))
    wobble = np.sqrt((ac ** 2).mean(axis=1)) + 1e-9
    chatter = np.mean(np.abs(np.diff(block, axis=1)), axis=1) + 1e-9
    return np.column_stack([20 * np.log10(level), 20 * np.log10(chatter), 20 * np.log10(wobble)])

NAMES = ["level in decibels", "chatter in decibels", "wobble in decibels"]

def fleet_table():
    rows, labels, groups = [], [], []
    for unit in range(UNITS):
        rows.append(features(raw_session(unit, is_worn(unit))))
        labels.append(np.full(BLOCKS, int(is_worn(unit))))
        groups.append(np.full(BLOCKS, unit))
    return np.vstack(rows), np.concatenate(labels), np.concatenate(groups)

def sigmoid(z):
    out = np.empty(z.shape, dtype=float)
    high = z >= 0
    out[high] = 1.0 / (1.0 + np.exp(-z[high]))
    low = np.exp(z[~high])
    out[~high] = low / (1.0 + low)
    return out

def linear(A, w):
    return (A * w).sum(axis=1)

def fit(A, y, lam=0.0, steps=3000, rate=0.5):
    w = np.zeros(A.shape[1])
    for _ in range(steps):
        grad = (A * (sigmoid(linear(A, w)) - y)[:, None]).sum(axis=0) / y.size
        grad[1:] = grad[1:] + lam * w[1:]
        w = w - rate * grad
    return w

def prepare(X, mu, sd):
    return np.column_stack([np.ones(X.shape[0]), (X - mu) / sd])

TEST_UNITS = [8, 9, 10, 11]

def frozen_split(X, y, group):
    test = np.isin(group, TEST_UNITS)
    mu, sd = X[~test].mean(axis=0), X[~test].std(axis=0)
    return prepare(X, mu, sd), test, mu, sd

PENALTIES = (0.0, 0.002, 0.02, 0.2)
X, y, group = fleet_table()
A, test, mu, sd = frozen_split(X, y, group)
train_units = [u for u in range(UNITS) if u not in TEST_UNITS]
FOLDS = [[u, u + 1] for u in (0, 2, 4, 6)]

def grouped_score(lam):
    out = []
    for held in FOLDS:
        rows = np.isin(group, held)
        inner = (~rows) & (~test)
        # TODO: fit on the other training units, score the units in this fold
        out.append(0.5)
    return float(np.mean(out))

print("folds of units", FOLDS)
